

# This file was *autogenerated* from the file /Users/masaori/git/masaori/math/.claude/worktrees/polished-sleeping-badger/exact-solution-of-2d-ising-model/sagemath/check/104_angle_section_existence_uniqueness/check_01_existence_uniqueness_and_floor.sage
from sage.all_cmdline import *   # import sage library

_sage_const_300 = Integer(300); _sage_const_2 = Integer(2); _sage_const_150 = Integer(150); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_100 = Integer(100); _sage_const_6 = Integer(6); _sage_const_3 = Integer(3); _sage_const_10 = Integer(10); _sage_const_7 = Integer(7); _sage_const_1000 = Integer(1000); _sage_const_22 = Integer(22); _sage_const_355 = Integer(355); _sage_const_113 = Integer(113); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_8 = Integer(8)# ---------------------------------------------------------
# <angle_section_existence_uniqueness>
#   theta in R について 0 <= theta - 2 n pi < 2 pi なる n in Z がただ一つ存在する。
#
# 検証の方法（独立経路）:
#   存在・一意性: floor を使わず、整数 n を十分広い窓で走査して
#     「条件 0 <= theta-2n pi < 2pi を満たす n」の個数を数える。ちょうど 1 個であること。
#   floor との一致: 別途 n' = floor(theta / 2pi) を計算し、走査で見つけた n と一致すること。
#   （走査は条件の直接評価、floor は別の計算経路なので、両者の一致は非自明な確認になる。）
#
# 境界: theta = 2 k pi ちょうど（n = k、theta-2n pi = 0）と
#       theta = 2 k pi - eps（n = k-1、theta-2n pi が 2pi の直下）を必ず含める。
#       境界の判定は 300 bit の実数演算で行い、|v| < 2^-150 を厳密な 0 とみなす。
#       theta は pi の有理数倍または有理数なので、非零な v がこの閾値を下回ることはない。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

RF = RealField(_sage_const_300 )
EPS0 = RF(_sage_const_2 ) ** (-_sage_const_150 )

def sgn0(v):
    r = RF(SR(v))
    if abs(r) < EPS0:
        return _sage_const_0 
    return _sage_const_1  if r > _sage_const_0  else -_sage_const_1 

def floor_tol(t):
    """floor。ただし t が整数から 2^-100 以内なら、その整数とみなす。
    theta = 2 k pi ちょうどのとき t = k を 300 bit 演算では厳密に表せないため
    （k pi の丸めで t = k - 2^-297 などになりうる）、この補正が要る。"""
    r = Integer(t.round())
    if abs(t - r) < RF(_sage_const_2 ) ** (-_sage_const_100 ):
        return r
    return Integer(t.floor())


def count_valid_n(theta, width=_sage_const_6 ):
    """0 <= theta - 2 n pi < 2 pi を満たす整数 n を窓の中で全部集める。"""
    theta = SR(theta)
    center = floor_tol(RF(theta) / RF(_sage_const_2  * pi))
    out = []
    for n in range(center - width, center + width + _sage_const_1 ):
        v = theta - _sage_const_2  * n * pi
        if sgn0(v) >= _sage_const_0  and sgn0(v - _sage_const_2  * pi) < _sage_const_0 :
            out.append(Integer(n))
    return out

# theta の候補: pi の有理数倍（境界 2 k pi ちょうどを含む）と有理数
THETAS = []
for k in [-_sage_const_3 , -_sage_const_2 , -_sage_const_1 , _sage_const_0 , _sage_const_1 , _sage_const_2 , _sage_const_3 , _sage_const_10 , -_sage_const_10 ]:
    THETAS.append(SR(_sage_const_2  * k) * pi)                       # 境界ちょうど（v=0）
    THETAS.append(SR(_sage_const_2  * k) * pi + SR(pi) / _sage_const_2 )
    THETAS.append(SR(_sage_const_2  * k) * pi + pi)
    THETAS.append(SR(_sage_const_2  * k) * pi + SR(_sage_const_3 ) / _sage_const_2  * pi)
    THETAS.append(SR(_sage_const_2  * k) * pi - SR(pi) / _sage_const_10 **_sage_const_6 )      # 2 pi の直下（v が 2pi 近傍）
    THETAS.append(SR(_sage_const_2  * k) * pi + SR(pi) / _sage_const_10 **_sage_const_6 )      # 0 の直上
for q in [_sage_const_0 , _sage_const_1 , -_sage_const_1 , QQ(_sage_const_1 )/_sage_const_3 , -QQ(_sage_const_1 )/_sage_const_3 , _sage_const_7 , -_sage_const_7 , _sage_const_1000 , -_sage_const_1000 , QQ(_sage_const_22 )/_sage_const_7 , -QQ(_sage_const_355 )/_sage_const_113 ]:
    THETAS.append(SR(q))
# 本プロジェクトで実際に現れる theta_mu = 2 pi mu / M
for M in [_sage_const_2 , _sage_const_3 , _sage_const_4 , _sage_const_5 , _sage_const_8 ]:
    for mu in range(-_sage_const_2  * M, _sage_const_2  * M + _sage_const_1 ):
        THETAS.append(SR(_sage_const_2  * mu) * pi / M)

rep = CheckReport("<angle_section_existence_uniqueness> 0<=theta-2n pi<2pi なる n の存在と一意性")

n_boundary = _sage_const_0 
for theta in THETAS:
    ns = count_valid_n(theta)
    ok = rep.truth(len(ns) == _sage_const_1 , "n はちょうど 1 個 (theta=%s, 見つかった n=%s)" % (theta, ns))
    if not ok:
        continue
    n = ns[_sage_const_0 ]
    v = theta - _sage_const_2  * n * pi
    rep.truth(sgn0(v) >= _sage_const_0 , "0 <= theta-2n pi (theta=%s)" % theta)
    rep.truth(sgn0(v - _sage_const_2  * pi) < _sage_const_0 , "theta-2n pi < 2pi (theta=%s)" % theta)
    if sgn0(v) == _sage_const_0 :
        n_boundary += _sage_const_1 
    # floor との一致
    n_floor = floor_tol(RF(theta) / RF(_sage_const_2  * pi))
    rep.truth(n == n_floor,
              "n = floor(theta/2pi) (theta=%s, n=%s, floor=%s)" % (theta, n, n_floor))

print("  走査した theta: %d 個、うち theta-2n pi = 0 ちょうど（境界）: %d 個"
      % (len(THETAS), n_boundary))

rep.finish()

